on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, pack, or generated odds are incomplete.
do $$
declare
  paradox_drive_cards integer;
  paradox_drive_packs integer;
  paradox_drive_odds integer;
begin
  select count(*)
  into paradox_drive_cards
  from public.cards
  where set_id = 'B3a';

  select count(*)
  into paradox_drive_packs
  from public.packs
  where set_id = 'B3a';

  select count(*)
  into paradox_drive_odds
  from public.card_pack_odds
  where pack_id = 'b3a-paradox-drive';

  if paradox_drive_cards <> 109 then
    raise exception
      'Expected 109 Paradox Drive cards, found %',
      paradox_drive_cards;
  end if;

  if paradox_drive_packs <> 1 then
    raise exception
      'Expected 1 Paradox Drive pack, found %',
      paradox_drive_packs;
  end if;

  if paradox_drive_odds <> 109 then
    raise exception
      'Expected 109 Paradox Drive odds rows, found %',
      paradox_drive_odds;
  end if;
end
$$;

commit;

-- Expected: 109 total records for the Paradox Drive pack.
select
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id = 'b3a-paradox-drive'
group by cards.rarity
order by min(cards.collector_number);
